#include "ViewerRuntime.h"
#include "V031Tests.h"
void RunV031Tests(const fs::path& directory,std::ostream& report){auto require=[&](bool ok,const char* label){if(!ok)throw std::runtime_error(label);report<<"PASS: "<<label<<'\n';};require(SearchContains(L"VRChat-山.JPG",L"vrchat")&&!SearchContains(L"foo.png",L"bar"),"search case-insensitive substring");auto old=ParseViewerSettings("{\"version\":2}");require(old.autoBackup&&old.backupLimit==10&&!old.darkTheme&&!old.metadataSearch,"v2 settings migrate with safe v0.3.1 defaults");auto folder=directory/L"overwrite-tests";fs::create_directories(folder);auto source=folder/L"original.png";fs::copy_file(directory/L"sample-日本語.png",source,fs::copy_options::overwrite_existing);auto ledger=folder/L"backups.json";fs::remove(ledger);MetadataEdit edit;edit.actions[1]=EditAction::Set;edit.values[1]=L"上書きテスト";auto before=MetadataFingerprint(source.wstring());auto warning=SaveMetadataOverwrite(source.wstring(),before,edit,true,10,ledger);require(warning.empty()&&InspectEditable(source.wstring()).values[1]==edit.values[1],"overwrite saves edited metadata");auto entries=ReadBackupLedger(ledger);require(entries.size()==1&&entries[0].sourceFingerprint==before&&MetadataFingerprint(entries[0].path)==entries[0].fingerprint&&InspectEditable(entries[0].path).values[5]==L"【AutoBackup】","automatic backup preserves pre-overwrite data with AutoBackup tag");require(InspectEditable(source.wstring()).values[5].empty(),"v0.4.15 source does not receive AutoBackup tag");auto unmanaged=folder/L"AB_unmanaged.png";fs::copy_file(source,unmanaged,fs::copy_options::overwrite_existing);auto candidates=FindBackups(folder.wstring(),ledger);require(candidates.size()==2&&std::count_if(candidates.begin(),candidates.end(),[](auto& c){return c.managed;})==1,"backup list distinguishes managed and unmanaged check defaults");bool rejected=false;try{SaveMetadataOverwrite(source.wstring(),before,edit,true,10,ledger);}catch(...){rejected=true;}require(rejected&&ReadBackupLedger(ledger).size()==1,"stale overwrite aborts without backup or source change");edit.values[1]=L"バックアップOFF";before=MetadataFingerprint(source.wstring());SaveMetadataOverwrite(source.wstring(),before,edit,false,10,ledger);require(ReadBackupLedger(ledger).size()==1&&InspectEditable(source.wstring()).values[1]==edit.values[1],"backup OFF overwrites without new backup");SetFileAttributesW(source.c_str(),FILE_ATTRIBUTE_READONLY);rejected=false;try{SaveMetadataOverwrite(source.wstring(),MetadataFingerprint(source.wstring()),edit,true,10,ledger);}catch(...){rejected=true;}SetFileAttributesW(source.c_str(),FILE_ATTRIBUTE_NORMAL);require(rejected,"read-only original overwrite rejected");auto originalNow=MetadataFingerprint(source.wstring());bool denied=false;auto blocked=folder/L"ledger-directory";fs::create_directories(blocked);try{SaveMetadataOverwrite(source.wstring(),originalNow,edit,true,10,blocked);}catch(...){denied=true;}require(denied&&MetadataFingerprint(source.wstring())==originalNow,"backup ledger failure leaves original unchanged");fs::remove(blocked);
    for(int i=0;i<3;++i){edit.values[1]=L"世代"+std::to_wstring(i);SaveMetadataOverwrite(source.wstring(),MetadataFingerprint(source.wstring()),edit,true,10,ledger);}
    auto generations=ReadBackupLedger(ledger);require(generations.size()==4,"repeated overwrites create unique backup names");
    auto changedBackup=generations.back().path;{std::ofstream out(changedBackup,std::ios::binary|std::ios::app);out.put('x');}
    auto locked=CreateFileW(generations[0].path.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);require(locked!=INVALID_HANDLE_VALUE,"backup deletion failure fixture locked");warning=PruneBackups(folder.wstring(),1,ledger);CloseHandle(locked);require(!warning.empty()&&fs::exists(generations[0].path)&&fs::exists(generations[1].path)&&fs::exists(generations[2].path),"old backup deletion failure retains newer generations");
    std::thread background([&]{winrt::init_apartment(winrt::apartment_type::multi_threaded);warning=PruneBackups(folder.wstring(),1,ledger);winrt::uninit_apartment();});background.join();require(warning.empty()&&!fs::exists(generations[0].path)&&!fs::exists(generations[1].path)&&fs::exists(generations[2].path)&&fs::exists(changedBackup)&&fs::exists(unmanaged),"backup cap recycles oldest managed files and preserves changed or unmanaged files");
    require(!RecycleBackup(source.wstring())&&fs::exists(source),"recycle rejects ordinary image names");
    for(auto& c:FindBackups(folder.wstring(),ledger))fs::remove(c.path);fs::remove(unmanaged);fs::remove(source);fs::remove(ledger);fs::remove(folder);}
